class Gallery(JsonData):
    DIR_MIME_TYPE = 'directory'

    def __init__(self, path):
        self.name = os.path.basename(path)
        self.path = path
        self.objects = []

        self.load()

    @staticmethod
    def get_by_path(path):
        path = os.path.normpath(path)
        gallery = Gallery(path)
        return gallery

    def load(self):
        self.objects.clear()

        if os.path.isdir(self.path):
            for name in os.listdir(self.path):
                object_path = os.path.join(self.path, name)
                self.objects.append(Object(object_path))

        logger.debug("%s loaded." % self.__class__.__name__)

    @property
    def objects(self):
        return self._objects

    @objects.setter
    def objects(self, objects):
        self._objects = objects

