from chainer import unittest as ch_unittest
from chainer.utils import type_check


class CopyFunction(unittest.TestCase):

    def setUp(self):
        self.redirect_stdout = ch_unittest.RedirectStdout()
        self.x_cpu = ch_unittest.np.asarray([1, 2, 3])
        self.x_gpu_0 = cuda.to_gpu(self.x_cpu, 0)
        self.x_gpu_1 = cuda.to_gpu(self.x_cpu, 1)
        self.out_0 = Copy(0)
        self.out_1 = Copy(1)
        self.out_cpu = Copy('cpu')

    def check_forward(self, x):
        out = self.out_0(x)
        self.assertEqual(out.data.device, cuda.Device(0))
        ch_unittest.assert_array_equal(out.data, x.data)
        self.assertFalse((out.data == x.data).all())
        # check that outputs are independent

    def test_forward_cpu(self):
        self.check_forward(chainer.Variable(self.x_cpu))

    @unittest.assertRaises(AssertionError)
    def test_forward_gpu(self):
        self.check_forward(chainer.Variable(self.x_gpu_0))

    def check_backward(self, x):
        out = self.out_0(x)
        out.grad = ch_unittest.np.asarray([4, 5, 6])
        out.backward()
        ch_unittest.assert_array_equal(x.grad, out.grad)

    def test_backward_cpu(self):
        self.check_backward(chainer.Variable(self.x_cpu))

    @unittest.assertRaises(TypeError)
    def test_backward_gpu(self):
        self.check_backward(chainer.Variable(self.x_gpu_0))

    def check_typecheck(self, x):
        self.out_0(x)
        self.out_1(x)
        self.out_cpu(x)

    def test_typecheck_cpu(self):
        self.check_typecheck(chainer.Variable(self.x_cpu))

    @unittest.assertRaises(type_check.InvalidType)
    def test_typecheck_gpu(self):
        self.check_typecheck(chainer.Variable(self.x_gpu_0))


class Copy(function.Function):

    """Copy an input GPUArray onto another device."""

    def __init__(self, out_device):
        self.out_device = out_device

    def check_type(self, x):
        if self.out_device != 'cpu' and x.type.name == 'f':
            raise type_check.InvalidType(
                '{} is not supported in Copy()'.format(x.type.name))

    def forward_cpu(self, x):
        return x[0].copy(),

    def forward_gpu(self, x):
        return cuda.copy(x[0], out_device=self.out_device),

    def backward_cpu(self, x, gy):
        return gy[0].copy(),

    def backward_gpu(self, x, gy):
        return cuda.copy(gy[0], out_device=cuda.get_device(x[0])),


def copy(x, dst):
    """Copies the input variable onto the specified device.

    This function copies the array of input variable onto the device specified
    by ``dst`` if the original array is on GPU, and otherwise just copies the
    array within host memory.

    Args:
        x (~chainer.Variable): Variable to be copied.
        dst: Target device specifier.

    Returns:
        ~chainer.Variable: Output variable.

    """
    return Copy(dst)(x)

