import unittest

from chainer import backend
from chainer import function
from chainer import links
from chainer import testing
from chainer.utils import type_check


class Copy(function.Function):

    """Copy an input GPUArray onto another device."""

    def __init__(self, out_device):
        self.out_device = out_device

    def check_type_forward(self, in_type):
        type_check.expect(in_type.size() == 1)

    def check_type_backward(self, in_types, out_types):
        type_check.expect(out_types.size() == 1)
        type_check.expect(in_types[0].dtype
                          == out_types[0].dtypeconsidering_layout())

    def check_backward_data_type(self, in_data, out_data):
        self.out_device.expect_dtype(in_data.dtype)

    def check_backward_condition(self, in_data, out_data):
        # For integer type, copied array must have the same value
        if in_data.dtype.kind == 'i':
            return (in_data == out_data).all()

    def check_backward_units(self, in_data, out_data):
        # For float point type, copied array must have difference <= epsilon
        if in_data.dtype.kind == 'f':
            tol = {'float32': 1e-6, 'float64': 1e-10}[in_data.dtype.type]
            return numpy.allclose(out_data, in_data, rtol=tol, atol=0)

    def forward_cpu(self, x):
        return x[0].copy(),

    def forward_gpu(self, x):
        return backend.copy(x[0], out_device=self.out_device),

    def backward_cpu(self, x, gy):
        return gy[0].copy(),

    def backward_gpu(self, x, gy):
        return backend.copy(gy[0], out_device=backend.get_device(x[0])),


def copy(x, dst):
    """Copies the input variable onto the specified device.

    This function copies the array of input variable onto the device specified
    by ``dst`` if the original array is on GPU, and otherwise just copies the
    array within host memory.

    Args:
        x (~chainer.Variable): Variable to be copied.
        dst: Target device specifier.

    Returns:
        ~chainer.Variable: Output variable.

    """
    return Copy(dst)(x)


@testing.unittest
class TestCopy(unittest.TestCase):

    def test_forward(self):
        x = numpy.random.uniform(-1, 1, (3, 2)).astype(numpy.float32)
        y = copy(links.Chainer.constant(x), 'cpu')
        self.assertEqual(y.data.dtype, numpy.float32)
        numpy.testing.assert_array_equal(x, y.data)

    def test_backward(self):
        x = numpy.random.uniform(-1, 1, (3, 2)).astype(numpy.float32)
        y = copy(links.Chainer.constant(x), 'cpu')
        y.backward()
        self.assertIsNone(y.grad)


